code.cpp:
class Solution {
public:
    int movesToMakeZigzag(vector<int>& nums) {
        int n = nums.size();
        int caseEvenPeaks = 0; // odd indices are valleys
        int caseOddPeaks  = 0; // even indices are valleys
        const int INF = 1001;
        for (int i = 0; i < n; i++) {
            int left  = (i > 0)     ? nums[i-1] : INF;
            int right = (i < n - 1) ? nums[i+1] : INF;
            int m = min(left, right);
            int cost = (nums[i] >= m) ? (nums[i] - m + 1) : 0;
            if (i % 2 == 0) caseOddPeaks  += cost;
            else            caseEvenPeaks += cost;
        }
        return min(caseEvenPeaks, caseOddPeaks);
    }
};
